// Componentes comuns às cenas: botão, HUD com a barra do próximo item e tela final.
export function botao(scene, x, y, w, h, texto, aoClicar, cor = 0x2f6fed) {
  const r = scene.add
    .rectangle(x, y, w, h, cor)
    .setStrokeStyle(3, 0xffffff)
    .setInteractive({ useHandCursor: true })
  const t = scene.add
    .text(x, y, texto, {
      fontSize: '20px',
      color: '#ffffff',
      align: 'center',
      wordWrap: { width: w - 16 },
    })
    .setOrigin(0.5)
  r.on('pointerdown', aoClicar)
  return {
    r,
    t,
    desativar() {
      r.disableInteractive()
      r.setAlpha(0.4)
      t.setAlpha(0.5)
    },
    destruir() {
      r.destroy()
      t.destroy()
    },
  }
}

export function criarHud(scene, ctx) {
  const larguraBarra = 220
  const rotulo = scene.add.text(20, 8, '', { fontSize: '18px', color: '#ffffff' })
  scene.add.rectangle(20, 38, larguraBarra, 12, 0x000000, 0.4).setOrigin(0, 0.5)
  const barra = scene.add.rectangle(20, 38, 1, 12, 0xffd447).setOrigin(0, 0.5)
  botao(scene, 740, 26, 90, 34, 'Sair', () => ctx.sair(), 0x555555)

  function atualizar(e) {
    if (e.proximo) {
      rotulo.setText(`Próximo: ${e.proximo.emoji} ${e.proximo.nome}`)
      const pct = (e.total - e.anterior) / (e.limite - e.anterior)
      barra.width = Math.max(1, larguraBarra * pct)
    } else {
      rotulo.setText('Coleção completa! 🎉')
      barra.width = larguraBarra
    }
    return e
  }

  function mostrarDesbloqueio(item) {
    const aviso = scene.add
      .text(400, 225, `Novo item!\n${item.emoji}\n${item.nome}`, {
        fontSize: '36px',
        color: '#ffffff',
        align: 'center',
        backgroundColor: '#000000cc',
        padding: { x: 24, y: 16 },
      })
      .setOrigin(0.5)
      .setDepth(10)
    if (ctx.efeitos) {
      aviso.setScale(0.2)
      scene.tweens.add({ targets: aviso, scale: 1, duration: 350, ease: 'Back.Out' })
    }
    scene.time.delayedCall(2200, () => aviso.destroy())
  }

  atualizar(ctx.estado())

  return {
    acerto() {
      const e = atualizar(ctx.registrarAcerto())
      if (e.novoItem) mostrarDesbloqueio(e.novoItem)
    },
  }
}

export function telaFinal(scene, ctx, mensagem) {
  scene.add.rectangle(400, 225, 800, 450, 0x000000, 0.7).setDepth(20)
  scene.add
    .text(400, 150, mensagem, { fontSize: '34px', color: '#ffffff', align: 'center' })
    .setOrigin(0.5)
    .setDepth(21)
  const a = botao(scene, 280, 280, 220, 60, 'Jogar de novo', () => scene.scene.restart(), 0x2e9e5b)
  const b = botao(scene, 520, 280, 220, 60, 'Voltar ao menu', () => ctx.sair(), 0x555555)
  for (const o of [a, b]) {
    o.r.setDepth(21)
    o.t.setDepth(22)
  }
}

export function embaralhar(lista) {
  const copia = [...lista]
  for (let i = copia.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[copia[i], copia[j]] = [copia[j], copia[i]]
  }
  return copia
}

import Phaser from 'phaser'
import { EMOCOES } from '../data/emocoes.js'
import { criarHud, telaFinal, embaralhar } from './ui.js'

const ACERTOS_POR_ALVO = 5
const META = 15

// Rostos caem e a criança pega só a emoção pedida. Errar não tira pontos.
export default class ChuvaEmocoes extends Phaser.Scene {
  constructor() {
    super('ChuvaEmocoes')
  }

  init() {
    this.ctx = this.registry.get('ctx')
  }

  create() {
    const { hiperfoco, nivel, velocidade } = this.ctx
    this.cameras.main.setBackgroundColor(hiperfoco.cor)

    this.emocoes = EMOCOES.slice(0, [3, 5, 7][nivel - 1] ?? 3)
    this.acertos = 0
    this.fim = false
    this.itens = []
    this.alvo = null

    this.hud = criarHud(this, this.ctx)
    this.titulo = this.add
      .text(400, 80, '', {
        fontSize: '28px',
        color: '#ffffff',
        backgroundColor: '#00000066',
        padding: { x: 12, y: 6 },
      })
      .setOrigin(0.5)
    this.dica = this.add
      .text(400, 125, '', { fontSize: '20px', color: '#ffe9a8' })
      .setOrigin(0.5)
    this.jogador = this.add.text(400, 410, hiperfoco.personagem, { fontSize: '56px' }).setOrigin(0.5)

    this.setas = this.input.keyboard.createCursorKeys()
    const seguir = (p) => {
      this.jogador.x = Phaser.Math.Clamp(p.x, 30, 770)
    }
    this.input.on('pointermove', seguir)
    this.input.on('pointerdown', seguir)

    this.novoAlvo()
    this.time.addEvent({ delay: 1400 / velocidade, loop: true, callback: () => this.soltar() })
  }

  novoAlvo() {
    const outras = this.emocoes.filter((e) => e !== this.alvo)
    this.alvo = embaralhar(outras)[0]
    this.titulo.setText(`Pegue: ${this.alvo.emoji} ${this.alvo.nome}`)
  }

  soltar() {
    if (this.fim) return
    const emocao = Math.random() < 0.5 ? this.alvo : embaralhar(this.emocoes)[0]
    const obj = this.add
      .text(Phaser.Math.Between(40, 760), -30, emocao.emoji, { fontSize: '44px' })
      .setOrigin(0.5)
    this.itens.push({ obj, emocao })
  }

  update(_, dt) {
    if (this.fim) return
    const { velocidade, nivel } = this.ctx
    const passo = dt / 1000

    if (this.setas.left.isDown) this.jogador.x -= 420 * passo
    if (this.setas.right.isDown) this.jogador.x += 420 * passo
    this.jogador.x = Phaser.Math.Clamp(this.jogador.x, 30, 770)

    const queda = 90 * velocidade * (1 + nivel * 0.15)
    for (const item of [...this.itens]) {
      item.obj.y += queda * passo
      const perto =
        Math.abs(item.obj.x - this.jogador.x) < 40 && Math.abs(item.obj.y - this.jogador.y) < 40
      if (perto) this.pegar(item)
      else if (item.obj.y > 480) this.remover(item)
    }
  }

  remover(item) {
    item.obj.destroy()
    this.itens = this.itens.filter((i) => i !== item)
  }

  pegar(item) {
    this.remover(item)
    if (item.emocao === this.alvo) {
      this.acertos++
      this.hud.acerto()
      this.dica.setText('✨ Isso!')
      if (this.acertos >= META) return this.terminar()
      if (this.acertos % ACERTOS_POR_ALVO === 0) this.novoAlvo()
    } else {
      this.dica.setText(`Quase! Procure: ${this.alvo.emoji} ${this.alvo.nome}`)
    }
    this.time.delayedCall(1200, () => this.dica.setText(''))
  }

  terminar() {
    this.fim = true
    telaFinal(this, this.ctx, 'Muito bem! 🎉\nVocê reconheceu as emoções!')
  }
}

import Phaser from 'phaser'
import { SITUACOES } from '../data/situacoes.js'
import { botao, criarHud, telaFinal, embaralhar } from './ui.js'

const RODADAS = 6
const XS = [230, 400, 570]
const BASE = { x: 110, y: 350 }

// O personagem encontra um amigo numa situação social e pula na plataforma da atitude certa.
export default class PlataformaAmigo extends Phaser.Scene {
  constructor() {
    super('PlataformaAmigo')
  }

  init() {
    this.ctx = this.registry.get('ctx')
  }

  create() {
    const { hiperfoco, nivel } = this.ctx
    this.cameras.main.setBackgroundColor(hiperfoco.cor)
    this.add.rectangle(400, 425, 800, 50, 0x000000, 0.35)

    this.situacoes = embaralhar(SITUACOES.filter((s) => s.nivel <= nivel)).slice(0, RODADAS)
    this.rodada = 0
    this.travado = false
    this.botoes = []

    this.hud = criarHud(this, this.ctx)
    this.balao = this.add
      .text(400, 105, '', {
        fontSize: '26px',
        color: '#ffffff',
        align: 'center',
        backgroundColor: '#00000066',
        padding: { x: 14, y: 8 },
        wordWrap: { width: 620 },
      })
      .setOrigin(0.5)
    this.jogador = this.add.text(BASE.x, BASE.y, hiperfoco.personagem, { fontSize: '56px' }).setOrigin(0.5)
    this.amigo = this.add.text(700, BASE.y, '🙂', { fontSize: '56px' }).setOrigin(0.5)

    ;['ONE', 'TWO', 'THREE'].forEach((tecla, i) =>
      this.input.keyboard.on(`keydown-${tecla}`, () => this.pular(i)),
    )
    this.mostrarSituacao()
  }

  duracao(ms) {
    return this.ctx.efeitos ? ms / this.ctx.velocidade : 1
  }

  mostrarSituacao() {
    const sit = this.situacoes[this.rodada]
    this.opcoes = embaralhar(sit.opcoes)
    this.amigo.setText('🙂')
    this.balao.setText(`${sit.texto}\nO que ${this.ctx.hiperfoco.personagemNome} faz?`)
    this.botoes.forEach((b) => b.destruir())
    this.botoes = this.opcoes.map((op, i) =>
      botao(this, XS[i], 250, 160, 90, `${i + 1}. ${op.texto}`, () => this.pular(i)),
    )
    this.travado = false
  }

  pular(i) {
    if (this.travado || !this.opcoes?.[i] || this.botoes[i].r.input?.enabled === false) return
    this.travado = true
    const op = this.opcoes[i]
    this.tweens.add({
      targets: this.jogador,
      x: XS[i],
      y: 175,
      duration: this.duracao(500),
      ease: 'Sine.Out',
      onComplete: () => (op.certo ? this.acertou(op) : this.errou(i, op)),
    })
  }

  acertou(op) {
    this.amigo.setText('😊')
    this.balao.setText(`Isso! ${op.feedback}`)
    this.hud.acerto()
    this.time.delayedCall(1800, () => {
      this.jogador.setPosition(BASE.x, BASE.y)
      this.rodada++
      if (this.rodada >= this.situacoes.length) {
        telaFinal(this, this.ctx, 'Muito bem! 🎉\nVocê ajudou todos os amigos!')
      } else {
        this.mostrarSituacao()
      }
    })
  }

  errou(i, op) {
    this.amigo.setText('😕')
    this.balao.setText(`Hmm... ${op.feedback}\nTente outra plataforma.`)
    this.botoes[i].desativar()
    this.tweens.add({
      targets: this.jogador,
      x: BASE.x,
      y: BASE.y,
      duration: this.duracao(500),
      ease: 'Sine.In',
      onComplete: () => (this.travado = false),
    })
  }
}

