    const bloco = this.add.rectangle(x1 + largura / 2, TOPO_CHAO + 30, largura, 60, 0x6b4a2b)
    this.add.rectangle(x1 + largura / 2, TOPO_CHAO + 5, largura, 10, 0x4caf50)
