export const FONTE = 'system-ui, "Segoe UI", sans-serif'

// Componentes comuns às cenas: botão, HUD com a barra do próximo item e tela final.
export function botao(scene, x, y, w, h, texto, aoClicar, cor = 0x2f6fed) {
  const r = scene.add
    .rectangle(x, y, w, h, cor)
    .setStrokeStyle(3, 0xffffff)
    .setInteractive({ useHandCursor: true })
    .setScrollFactor(0)
  const t = scene.add
    .text(x, y, texto, {
      fontFamily: FONTE, fontSize: '20px',
      color: '#ffffff',
      align: 'center',
      wordWrap: { width: w - 16 },
    })
    .setOrigin(0.5)
    .setScrollFactor(0)
  r.on('pointerdown', aoClicar)
  return {
    r,
    t,
    desativar() {
      r.disableInteractive()
      r.setAlpha(0.4)
      t.setAlpha(0.5)
    },
    destruir() {
      r.destroy()
      t.destroy()
    },
  }
}

export function criarHud(scene, ctx) {
  const larguraBarra = 220
  // fixo na tela (scrollFactor 0) e acima do cenário, para cenas com câmera que rola
  const fixo = (o) => o.setScrollFactor(0).setDepth(40)
  const rotulo = fixo(
    scene.add.text(20, 8, '', { fontFamily: FONTE, fontSize: '18px', color: '#ffffff' }),
  )
  fixo(scene.add.rectangle(20, 38, larguraBarra, 12, 0x000000, 0.4).setOrigin(0, 0.5))
  const barra = fixo(scene.add.rectangle(20, 38, 1, 12, 0xffd447).setOrigin(0, 0.5))
  const sair = botao(scene, 740, 26, 90, 34, 'Sair', () => ctx.sair(), 0x555555)
  sair.r.setDepth(40)
  sair.t.setDepth(41)

  function atualizar(e) {
    if (e.proximo) {
      rotulo.setText(`Próximo: ${e.proximo.emoji} ${e.proximo.nome}`)
      const pct = (e.total - e.anterior) / (e.limite - e.anterior)
      barra.width = Math.max(1, larguraBarra * pct)
    } else {
      rotulo.setText('Coleção completa! 🎉')
      barra.width = larguraBarra
    }
    return e
  }

  function mostrarDesbloqueio(item) {
    const aviso = scene.add
      .text(400, 225, `Novo item!\n${item.emoji}\n${item.nome}`, {
        fontFamily: FONTE, fontSize: '36px',
        color: '#ffffff',
        align: 'center',
        backgroundColor: '#000000cc',
        padding: { x: 24, y: 16 },
      })
      .setOrigin(0.5)
      .setScrollFactor(0)
      .setDepth(45)
    if (ctx.efeitos) {
      aviso.setScale(0.2)
      scene.tweens.add({ targets: aviso, scale: 1, duration: 350, ease: 'Back.Out' })
    }
