    this.acertos = 0
    this.fim = false
    this.itens = []
    this.alvo = null

    this.hud = criarHud(this, this.ctx)
    this.titulo = this.add
      .text(400, 80, '', {
        fontFamily: FONTE, fontSize: '28px',
        color: '#ffffff',
        backgroundColor: '#00000066',
        padding: { x: 12, y: 6 },
