import puppeteer from 'puppeteer-core'
const b = await puppeteer.launch({ executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe', headless: true })
const p = await b.newPage()
await p.setViewport({ width: 1000, height: 700 })
const erros = []
p.on('pageerror', (e) => erros.push('pageerror: ' + e.message))
p.on('console', (m) => { if (m.type() === 'error') erros.push('console: ' + m.text()) })
const esperar = (ms) => new Promise((r) => setTimeout(r, ms))
const clicar = async (txt) => { const [h] = await p.$$(`xpath/.//button[contains(., "${txt}")]`); if (!h) throw new Error('sem botão ' + txt); await h.click() }

await p.goto('http://localhost:5173/')
await p.evaluate(() => localStorage.setItem('dopamine-progresso-v1', JSON.stringify({ trem: 3 })))
await p.reload()
await p.type('input', 'Teste')
await clicar('Preencher exemplo'); await clicar('Continuar'); await clicar('Trem')
const abrir = async (i) => { const bs = await p.$$('.cartao button'); await bs[i].click(); await esperar(1500) }
const sair = async () => { const c = await p.$('canvas'); const bb = await c.boundingBox(); await p.mouse.click(bb.x + bb.width * 0.925, bb.y + bb.height * 0.058); await esperar(300) }

// Chuva
await abrir(0); await p.mouse.move(400, 500); await esperar(2500)
console.log('fonte:', await p.evaluate(() => document.fonts.check('700 20px Fredoka')))
await p.screenshot({ path: 'v_chuva.png', clip: { x: 60, y: 80, width: 880, height: 500 } }); await sair()
// História
await abrir(1)
await p.screenshot({ path: 'v_historia.png', clip: { x: 60, y: 80, width: 880, height: 500 } }); await sair()
// Plataforma com diálogo
await abrir(2)
await p.evaluate(() => { const s = window.__phaser.scene.scenes[0]; s.encontrar(s.zonasAmigo[0].amigo) })
await esperar(600)
await p.screenshot({ path: 'v_plataforma.png', clip: { x: 60, y: 80, width: 880, height: 500 } })
console.log('erros:', erros)
await b.close()

