      barra.setSize(larguraBarra, 10)
    }
    return e
  }

  function mostrarDesbloqueio(item) {
    const aviso = caixaTexto(
      scene,
      400,
      225,
      `Novo item!\n${item.emoji}\n${item.nome}`,
      { fontSize: '36px', color: '#ffffff', align: 'center' },
      { px: 28, py: 18, alpha: 0.85, depth: 45, fixo: true },
    )
    if (ctx.efeitos) {
      aviso.f.setScale(0.2)
      aviso.t.setScale(0.2)
      scene.tweens.add({ targets: [aviso.f, aviso.t], scale: 1, duration: 350, ease: 'Back.Out' })
    }
    scene.time.delayedCall(2200, () => aviso.destroy())
  }

  atualizar(ctx.estado())

  return {
    // acerto avança a coleção e entra no desempenho; erro só entra no desempenho
    acerto() {
      ctx.registrarTentativa(true)
      const e = atualizar(ctx.registrarAcerto())
      if (e.novoItem) mostrarDesbloqueio(e.novoItem)
    },
    erro() {
      ctx.registrarTentativa(false)
    },
  }
}

export function telaFinal(scene, ctx, mensagem) {
  scene.add.rectangle(400, 225, 800, 450, 0x000000, 0.7).setScrollFactor(0).setDepth(50)
  caixaTexto(
    scene,
    400,
    150,
    mensagem,
    { fontSize: '34px', color: '#ffffff', align: 'center' },
    { px: 32, py: 16, alpha: 0.5, depth: 51, fixo: true },
  )
  const a = botao(scene, 280, 280, 220, 60, 'Jogar de novo', () => scene.scene.restart(), 0x2e9e5b)
  const b = botao(scene, 520, 280, 220, 60, 'Voltar ao menu', () => ctx.sair(), 0x555555)
  for (const o of [a, b]) {
    o.r.setDepth(53)
    o.t.setDepth(54)
  }
}

export function embaralhar(lista) {
  const copia = [...lista]
  for (let i = copia.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[copia[i], copia[j]] = [copia[j], copia[i]]
  }
  return copia
}

import { useEffect, useRef } from 'react'
import Phaser from 'phaser'
import ChuvaEmocoes from './games/ChuvaEmocoes.js'
import PlataformaAmigo from './games/PlataformaAmigo.js'
import HistoriaEscolhas from './games/HistoriaEscolhas.js'

const CENAS = { ChuvaEmocoes, PlataformaAmigo, HistoriaEscolhas }

// ctx: { hiperfoco, nivel, velocidade, efeitos, sair, estado, registrarAcerto }
export default function PhaserGame({ cena, ctx }) {
  const containerRef = useRef(null)
  const ctxRef = useRef(ctx)

  useEffect(() => {
    ctxRef.current = ctx
  })

  useEffect(() => {
    let game
    let cancelado = false

    // o canvas só desenha com a fonte do jogo depois que ela carregou
    Promise.all([
      document.fonts.load('400 20px Fredoka'),
      document.fonts.load('700 20px Fredoka'),
    ])
      .catch(() => {})
      .then(() => {
        if (cancelado) return
        game = new Phaser.Game({
          type: Phaser.AUTO,
          parent: containerRef.current,
          width: 800,
          height: 450,
          scale: { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_HORIZONTALLY },
          physics: { default: 'arcade', arcade: { gravity: { y: 1100 } } },
          scene: [CENAS[cena]],
          callbacks: { preBoot: (g) => g.registry.set('ctx', ctxRef.current) },
        })
        // só para testes automáticos no modo de desenvolvimento
        if (import.meta.env.DEV) window.__phaser = game
      })

    return () => {
      cancelado = true
      game?.destroy(true)
    }
  }, [cena])

  return <div ref={containerRef} className="jogo" />
}

