import Phaser from 'phaser'
import { EMOCOES } from '../data/emocoes.js'
import { FONTE, caixaTexto, criarHud, telaFinal, embaralhar } from './ui.js'

const ACERTOS_POR_ALVO = 5
const META = 15

// Rostos caem e a criança pega só a emoção pedida. Errar não tira pontos.
export default class ChuvaEmocoes extends Phaser.Scene {
  constructor() {
    super('ChuvaEmocoes')
  }

  init() {
    this.ctx = this.registry.get('ctx')
  }

  create() {
    const { hiperfoco, nivel, velocidade } = this.ctx
    this.cameras.main.setBackgroundColor(hiperfoco.cor)

    this.emocoes = EMOCOES.slice(0, [3, 5, 7][nivel - 1] ?? 3)
    this.acertos = 0
    this.fim = false
    this.itens = []
    this.alvo = null

    this.hud = criarHud(this, this.ctx)
    this.titulo = caixaTexto(this, 400, 90, '', { fontSize: '28px', color: '#ffffff' }, { alpha: 0.4 })
    this.dica = caixaTexto(
      this,
      400,
      138,
      '',
      { fontSize: '20px', color: '#ffe9a8' },
      { px: 12, py: 5, alpha: 0.35 },
    )
    this.jogador = this.add.text(400, 410, hiperfoco.personagem, { fontFamily: FONTE, fontSize: '56px' }).setOrigin(0.5)

    this.setas = this.input.keyboard.createCursorKeys()
    const seguir = (p) => {
      this.jogador.x = Phaser.Math.Clamp(p.x, 30, 770)
    }
    this.input.on('pointermove', seguir)
    this.input.on('pointerdown', seguir)

    this.novoAlvo()
    this.time.addEvent({ delay: 1400 / velocidade, loop: true, callback: () => this.soltar() })
  }

  novoAlvo() {
    const outras = this.emocoes.filter((e) => e !== this.alvo)
    this.alvo = embaralhar(outras)[0]
    this.titulo.setText(`Pegue: ${this.alvo.emoji} ${this.alvo.nome}`)
  }

  soltar() {
    if (this.fim) return
    const emocao = Math.random() < 0.5 ? this.alvo : embaralhar(this.emocoes)[0]
    const obj = this.add
      .text(Phaser.Math.Between(40, 760), -30, emocao.emoji, { fontFamily: FONTE, fontSize: '44px' })
      .setOrigin(0.5)
    this.itens.push({ obj, emocao })
  }

  update(_, dt) {
    if (this.fim) return
    const { velocidade, nivel } = this.ctx
    const passo = dt / 1000

    if (this.setas.left.isDown) this.jogador.x -= 420 * passo
    if (this.setas.right.isDown) this.jogador.x += 420 * passo
    this.jogador.x = Phaser.Math.Clamp(this.jogador.x, 30, 770)

    const queda = 90 * velocidade * (1 + nivel * 0.15)
    for (const item of [...this.itens]) {
      item.obj.y += queda * passo
      const perto =
        Math.abs(item.obj.x - this.jogador.x) < 40 && Math.abs(item.obj.y - this.jogador.y) < 40
      if (perto) this.pegar(item)
      else if (item.obj.y > 480) this.remover(item)
    }
  }

  remover(item) {
    item.obj.destroy()
    this.itens = this.itens.filter((i) => i !== item)
  }

  pegar(item) {
    this.remover(item)
    if (item.emocao === this.alvo) {
      this.acertos++
      this.hud.acerto()
      this.dica.setText('✨ Isso!')
      if (this.acertos >= META) return this.terminar()
      if (this.acertos % ACERTOS_POR_ALVO === 0) this.novoAlvo()
    } else {
      this.hud.erro()
      this.dica.setText(`Quase! Procure: ${this.alvo.emoji} ${this.alvo.nome}`)
    }
    this.time.delayedCall(1200, () => this.dica.setText(''))
  }

  terminar() {
    this.fim = true
    telaFinal(this, this.ctx, 'Muito bem! 🎉\nVocê reconheceu as emoções!')
  }
}

import Phaser from 'phaser'
import { HISTORIAS } from '../data/historias.js'
import { FONTE, RAIO, botao, caixaTexto, criarHud, telaFinal, embaralhar } from './ui.js'
import { sortear } from '../variedade.js'

// Jogo calmo e sem tempo: a criança escolhe o que o personagem faz e vê a consequência.
export default class HistoriaEscolhas extends Phaser.Scene {
  constructor() {
    super('HistoriaEscolhas')
  }

  init() {
    this.ctx = this.registry.get('ctx')
  }

  create() {
    const { hiperfoco, nivel } = this.ctx
    this.cameras.main.setBackgroundColor(hiperfoco.cor)
    // não repete a história até a criança ter visto todas as do nível
    this.historia = sortear(
      `historia:${this.ctx.aluno}`,
      HISTORIAS.filter((h) => h.nivel <= nivel),
      1,
      (h) => h.titulo,
    )[0]
    this.passo = 0
    this.botoes = []

    this.hud = criarHud(this, this.ctx)
    caixaTexto(
      this,
      400,
      68,
      this.historia.titulo,
      { fontSize: '22px', color: '#ffe9a8' },
      { px: 16, py: 5, alpha: 0.35 },
    )
    // painel de leitura atrás da história e da consequência
    this.add.rectangle(450, 175, 680, 150, 0x000000, 0.25).setRounded(RAIO + 4)
    this.add.text(60, 125, hiperfoco.personagem, { fontFamily: FONTE, fontSize: '64px' }).setOrigin(0.5)
    this.texto = this.add
      .text(130, 100, '', { fontFamily: FONTE, fontSize: '24px', color: '#ffffff', wordWrap: { width: 620 } })
    this.retorno = this.add
      .text(130, 205, '', { fontFamily: FONTE, fontSize: '22px', color: '#ffe9a8', wordWrap: { width: 620 } })

    this.mostrarPasso()
  }

  trocar(texto) {
    const frase = texto.replaceAll('{p}', this.ctx.hiperfoco.personagemNome)
    return frase[0].toUpperCase() + frase.slice(1)
  }

  mostrarPasso() {
    const passo = this.historia.passos[this.passo]
    this.travado = false
    this.retorno.setText('')
    this.texto.setText(this.trocar(passo.texto))
    this.botoes.forEach((b) => b.destruir())
    this.botoes = embaralhar(passo.escolhas).map((escolha, i) => {
      const b = botao(this, 400, 295 + i * 62, 640, 50, escolha.texto, () => this.escolher(b, escolha))
      return b
    })
  }

  escolher(b, escolha) {
    if (this.travado) return
    this.retorno.setText(this.trocar(escolha.consequencia))
    if (!escolha.certo) {
      this.hud.erro()
      return b.desativar()
    }

    this.travado = true
    this.botoes.forEach((x) => x.desativar())
    this.hud.acerto()
    this.time.delayedCall(2200, () => {
      this.passo++
      if (this.passo >= this.historia.passos.length) this.terminar()
      else this.mostrarPasso()
    })
  }

  terminar() {
    telaFinal(this, this.ctx, `${this.trocar(this.historia.final)}\n🎉`)
  }
}

