import puppeteer from 'puppeteer-core'
const b = await puppeteer.launch({
  executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe',
  headless: true,
  args: ['--autoplay-policy=no-user-gesture-required'],
})
const p = await b.newPage()
await p.setViewport({ width: 1000, height: 700 })
const erros = []
p.on('pageerror', (e) => erros.push('pageerror: ' + e.message))
p.on('console', (m) => { if (m.type() === 'error') erros.push('console: ' + m.text()) })
// conta os osciladores criados, para saber se há som
await p.evaluateOnNewDocument(() => {
  window.__osc = 0
  const original = AudioContext.prototype.createOscillator
  AudioContext.prototype.createOscillator = function () { window.__osc++; return original.call(this) }
})
const esperar = (ms) => new Promise((r) => setTimeout(r, ms))
const clicar = async (txt) => { const [h] = await p.$$(`xpath/.//button[contains(., "${txt}")]`); if (!h) throw new Error('sem botão ' + txt); await h.click() }
const osc = () => p.evaluate(() => window.__osc)
const marcar = (el) => p.evaluate((sel) => { const e = document.querySelector(sel); e.click() }, el)

await p.goto('http://localhost:5173/')
await p.evaluate(() => localStorage.clear())
await p.reload()
await p.type('input', 'Anim')
await clicar('Preencher exemplo'); await clicar('Continuar'); await clicar('Trem')
const abrir = async (i) => { const bs = await p.$$('.cartao button'); await bs[i].click(); await esperar(1200) }
const sair = async () => { const c = await p.$('canvas'); const bb = await c.boundingBox(); await p.mouse.click(bb.x + bb.width * 0.925, bb.y + bb.height * 0.058); await esperar(400) }
const rotulos = await p.$$eval('.opcoes label', (ls) => ls.map((l) => l.innerText.trim()))
console.log('opções na tela:', rotulos)

// 1) música e sons ligados
await abrir(2) // Plataforma
const aposMusica = await osc()
await esperar(2500)
console.log('osciladores só com a música (3,7 s):', await osc())
await p.evaluate(() => { const s = window.__phaser.scene.scenes[0]; s.hud.acerto({ x: s.jogador.x, y: s.jogador.y }); })
await esperar(250)
await p.screenshot({ path: 'a_confete.png', clip: { x: 60, y: 80, width: 880, height: 500 } })
console.log('osciladores após um acerto:', await osc())
await sair()
const parou = await osc(); await esperar(2000)
console.log('música parou ao sair:', (await osc()) === parou)

// 2) tudo desligado
await clicar('Música') .catch(() => {})
await p.evaluate(() => { for (const l of document.querySelectorAll('.opcoes label')) { const i = l.querySelector('input'); if (/Sons|Música/.test(l.innerText) && i.checked) i.click() } })
const antes = await osc()
await abrir(0) // Chuva
await p.evaluate(() => { const s = window.__phaser.scene.scenes[0]; s.hud.acerto(s.jogador); s.hud.erro() })
await esperar(1500)
console.log('osciladores com som e música desligados:', (await osc()) - antes)
await p.screenshot({ path: 'a_chuva.png', clip: { x: 60, y: 80, width: 880, height: 500 } })
await sair()

// 3) celebração ao desbloquear (5º acerto) e fim de jogo
await p.evaluate(() => localStorage.setItem('dopamine-progresso-v1', JSON.stringify({ trem: 4 })))
await p.reload()
await p.type('input', 'Anim')
await clicar('Preencher exemplo'); await clicar('Continuar'); await clicar('Trem')
await abrir(0)
await p.evaluate(() => { const s = window.__phaser.scene.scenes[0]; s.hud.acerto(s.jogador) })
await esperar(400)
await p.screenshot({ path: 'a_desbloqueio.png', clip: { x: 60, y: 80, width: 880, height: 500 } })
await p.evaluate(() => { const s = window.__phaser.scene.scenes[0]; s.terminar() })
await esperar(700)
await p.screenshot({ path: 'a_fim.png', clip: { x: 60, y: 80, width: 880, height: 500 } })
console.log('erros:', erros)
await b.close()

